customScripts.iel_meta:
(function(){
  var root = (typeof __mfCurrentScriptRoot !== 'undefined' && __mfCurrentScriptRoot) || document;
  var scope = (root && root.closest) ? (root.closest('.mfp') || document) : document;
  function put(k, v){ var n = scope.querySelector('[data-iel="' + k + '"]'); if (n) n.textContent = v; }
  put('today', new Date().toLocaleDateString('en-GB'));
  function cand(){
    var i = scope.querySelector('[name="candidate_id"]');
    put('cand', (i && i.value) ? i.value : '\u2014');
  }
  scope.addEventListener('input', cand, true);
  scope.addEventListener('change', cand, true);
  cand();
})();

settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
.mfp.mfp-iel.mfp-native-generated {--iel-primary:#111318;--iel-accent:#B3242A;--iel-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--iel-text:var(--mf-page-text,var(--mf-preset-text,#111318));--iel-muted:var(--mf-page-muted,var(--mf-preset-muted,#6B7280));--iel-border:var(--mf-page-border,var(--mf-preset-border,#D6D9DE));--iel-on-primary:var(--mf-preset-on-primary,#FFFFFF);--iel-deco:#F4F5F7;--iel-page:#EEF0F3;--iel-fill:#EEF0F3;--iel-fill-strong:color-mix(in srgb, var(--iel-text) 9%, var(--iel-surface));--iel-soft:color-mix(in srgb, var(--iel-primary) 12%, var(--iel-surface));--iel-hairline:color-mix(in srgb, var(--iel-text) 12%, var(--iel-surface));}.mfp.mfp-iel.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-iel.mfp-native-generated {--iel-primary:var(--mf-page-primary,var(--mf-preset-primary,#111318));--iel-accent:var(--mf-page-accent,var(--mf-preset-accent,#B3242A));--iel-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--iel-text:var(--mf-page-text,var(--mf-preset-text,#111318));--iel-border:var(--mf-page-border,var(--mf-preset-border,#D6D9DE));--iel-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FFFFFF));--iel-page:var(--mf-preset-bg,#EEF0F3);}@container (max-width:520px){.mfp.mfp-iel.mfp-native-generated [class*="-grid"],.mfp.mfp-iel.mfp-native-generated [class*="-meta"],.mfp.mfp-iel.mfp-native-generated [class*="-scores"],.mfp.mfp-iel.mfp-native-generated [class*="-charts"],.mfp.mfp-iel.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-iel.mfp-native-generated [class*="-body"],.mfp.mfp-iel.mfp-native-generated [class*="-split"],.mfp.mfp-iel.mfp-native-generated [class*="-foot"],.mfp.mfp-iel.mfp-native-generated [class*="-head"],.mfp.mfp-iel.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-iel.mfp-native-generated [class*="-aside"],.mfp.mfp-iel.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-iel.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-iel.mfp-native-generated {overflow-wrap:break-word}

/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-iel){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-iel) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-iel) .mf-form,
.mf-form-wrapper:has(.mfp-iel) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

.mfp.mfp-iel.mfp-native-generated {container-type:inline-size;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated .iel-page{padding:40px 0;background:var(--iel-page)}
.mfp.mfp-iel.mfp-native-generated .iel-shell{max-width:768px;margin:0 auto;padding:0 16px}
.mfp.mfp-iel.mfp-native-generated .iel-back{font-size:16px;line-height:24px}
.mfp.mfp-iel.mfp-native-generated .iel-back-link{display:inline-flex;align-items:center;gap:6px;margin-bottom:24px;font-size:12px;
  line-height:16px;font-weight:500;color:#6B7280}
.mfp.mfp-iel.mfp-native-generated .iel-back-ico{display:block;flex:0 0 14px;width:14px;height:14px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%236B7280' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M19 12H5'%2F%3E%3Cpath d='m12 19-7-7 7-7'%2F%3E%3C%2Fsvg%3E") center/14px 14px no-repeat}
.mfp.mfp-iel.mfp-native-generated .iel-card{border:1px solid var(--iel-border);border-radius:8px;background:#fff;
  box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}

/* header ----------------------------------------------------------------- */
.mfp.mfp-iel.mfp-native-generated .iel-head{display:flex;align-items:flex-start;justify-content:space-between;
  padding:24px 32px;border-bottom:1px solid var(--iel-border)}
.mfp.mfp-iel.mfp-native-generated .iel-brand{font-size:30px;line-height:36px;font-weight:800;letter-spacing:-.025em;color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated .iel-sub{margin-top:4px;font-size:14px;line-height:20px;font-weight:600;color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated .iel-badge{display:inline-block;padding:6px 12px;border:1.5px solid var(--iel-primary);border-radius:6px;
  font-size:12px;line-height:16px;font-weight:700;letter-spacing:.025em;text-transform:uppercase;
  color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated .iel-note{padding:12px 32px;background:#F4F5F7;font-size:11px;line-height:1.625;color:#6B7280}
.mfp.mfp-iel.mfp-native-generated .iel-note-k{font-weight:700;color:var(--iel-primary)}

/* body ------------------------------------------------------------------- */
.mfp.mfp-iel.mfp-native-generated .iel-body{padding:24px 32px}
.mfp.mfp-iel.mfp-native-generated .iel-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px;
  padding-bottom:24px;border-bottom:1px solid var(--iel-border)}
.mfp.mfp-iel.mfp-native-generated .iel-meta-c{padding:8px;border-radius:6px;background:#F4F5F7}
.mfp.mfp-iel.mfp-native-generated .iel-meta-k{font-size:10px;line-height:1.5;font-weight:600;text-transform:uppercase;
  color:#6B7280}
.mfp.mfp-iel.mfp-native-generated .iel-meta-v{margin-top:4px;font-size:14px;line-height:20px;font-weight:500;color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated h2.iel-h2{margin:0 0 16px!important;font-size:14px!important;line-height:20px!important;
  font-weight:700!important;letter-spacing:.025em!important;text-transform:uppercase!important;
  color:var(--iel-primary)!important}
.mfp.mfp-iel.mfp-native-generated h2.iel-h2-b{margin-top:32px!important}
.mfp.mfp-iel.mfp-native-generated .iel-grid2{display:grid;grid-template-columns:1fr;gap:16px}
@container (min-width:640px){.mfp.mfp-iel.mfp-native-generated .iel-grid2{grid-template-columns:1fr 1fr}}
.mfp.mfp-iel.mfp-native-generated .iel-field{display:block;margin:0}
.mfp.mfp-iel.mfp-native-generated .iel-label{display:block;margin:0 0 4px;font-size:11px;line-height:1.5;font-weight:600;
  letter-spacing:.025em;text-transform:uppercase;color:#6B7280}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-iel.mfp-native-generated label,.mfp.mfp-iel.mfp-native-generated span,.mfp.mfp-iel.mfp-native-generated p,.mfp.mfp-iel.mfp-native-generated div,.mfp.mfp-iel.mfp-native-generated ul,.mfp.mfp-iel.mfp-native-generated li,.mfp.mfp-iel.mfp-native-generated h1,.mfp.mfp-iel.mfp-native-generated h2,.mfp.mfp-iel.mfp-native-generated h3,.mfp.mfp-iel.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-iel.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-iel.mfp-native-generated .mf-section-break,.mfp.mfp-iel.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-iel.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-iel.mfp-native-generated .mf-form-title,.mfp.mfp-iel.mfp-native-generated .mf-form-description,.mfp.mfp-iel.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-iel.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-iel.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-iel.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-iel.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-iel.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-iel.mfp-native-generated .mf-input[class],.mfp.mfp-iel.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--iel-border)!important;border-radius:6px!important;background:var(--iel-surface)!important;
  padding:8px 12px!important;min-height:0!important;height:auto!important;
  color:rgb(8,12,15)!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:400!important;box-shadow:none!important}
.mfp.mfp-iel.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-iel.mfp-native-generated .mf-select[class]:focus{border-color:var(--iel-primary)!important;
  box-shadow:none!important;outline:none!important}
.mfp.mfp-iel.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-iel.mfp-native-generated .mf-textarea[class]::placeholder{color:rgba(8,12,15,.5)!important;opacity:1}


/* The selects carry their empty colour inline in the mock; the inputs do not, so this cannot come
   out of boxedControls' single ph value. */
.mfp.mfp-iel.mfp-native-generated .mf-select[class]:invalid,.mfp.mfp-iel.mfp-native-generated .mf-select[class]:has(option[value=""]:checked){
  color:#94A3B8!important}

/* Date control: the mock's is native, ours is a button + popover. Same treatment as every other
   exact conversion - ink text inset 4px, 10x12 black indicator 20px off the right border. */
.mfp.mfp-iel.mfp-native-generated .iel-field .mf-cal.is-empty .mf-cal-value,.mfp.mfp-iel.mfp-native-generated .iel-field .mf-cal-value{
  color:rgb(8,12,15)!important;padding-left:4px;padding-right:24px}
.mfp.mfp-iel.mfp-native-generated .iel-field .mf-cal .mf-date-icon{position:absolute!important;right:20px!important;
  width:10px!important;height:12px!important;flex:0 0 10px!important;color:#000!important}
.mfp.mfp-iel.mfp-native-generated .iel-field .mf-cal .mf-date-icon svg{width:10px!important;height:12px!important;
  stroke-width:2!important}

/* band row --------------------------------------------------------------- */
.mfp.mfp-iel.mfp-native-generated .iel-scores{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.mfp.mfp-iel.mfp-native-generated .iel-score{padding:12px;border:1px solid var(--iel-border);border-radius:6px;text-align:center}
.mfp.mfp-iel.mfp-native-generated .iel-score-v{font-size:18px;line-height:28px;font-weight:700;color:var(--iel-primary)}
.mfp.mfp-iel.mfp-native-generated .iel-score-k{margin-top:2px;font-size:10px;line-height:1.5;font-weight:400;
  letter-spacing:.025em;text-transform:uppercase;color:#6B7280}
.mfp.mfp-iel.mfp-native-generated .iel-score-band{border:2px solid var(--iel-accent)}
.mfp.mfp-iel.mfp-native-generated .iel-band-k{margin-top:2px;font-size:10px;line-height:1.5;font-weight:600;letter-spacing:.025em;
  text-transform:uppercase;color:var(--iel-accent)}
/* the overall-band select is bare in the mock: no border, no fill, centred 18px/28 bold */
.mfp.mfp-iel.mfp-native-generated .iel-band-w .mf-select[class]{border:0!important;border-radius:0!important;
  background:transparent!important;padding:0!important;text-align:center!important;
  text-align-last:center!important;font-size:18px!important;line-height:28px!important;
  font-weight:700!important;color:var(--iel-accent)!important}
.mfp.mfp-iel.mfp-native-generated .iel-band-w .mf-select[class]:invalid,
.mfp.mfp-iel.mfp-native-generated .iel-band-w .mf-select[class]:has(option[value=""]:checked){color:#94A3B8!important}
/* megaform paints its own chevron beside a select (.mf-select-chevron, absolutely positioned in
   .mf-select-wrap) and reserves 42px of padding for it; the mock's band select has neither. */
.mfp.mfp-iel.mfp-native-generated .iel-band-w .mf-select-chevron{display:none!important}
.mfp.mfp-iel.mfp-native-generated .iel-band-w .mf-select-wrap .mf-select[class]{padding-right:0!important}

/* footer ----------------------------------------------------------------- */
.mfp.mfp-iel.mfp-native-generated .iel-foot{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;
  margin-top:32px;padding-top:24px;border-top:1px solid var(--iel-border)}
.mfp.mfp-iel.mfp-native-generated .iel-admin{flex:1 1 0;padding:12px;border:1px solid var(--iel-border);border-radius:6px;background:#F4F5F7}
.mfp.mfp-iel.mfp-native-generated .iel-admin-k{font-size:10px;line-height:1.5;font-weight:600;text-transform:uppercase;
  color:#6B7280}
.mfp.mfp-iel.mfp-native-generated .iel-admin-v{margin-top:8px;height:56px;font-size:14px;line-height:20px;font-weight:400;
  font-style:italic;color:#B0B4BC}
.mfp.mfp-iel.mfp-native-generated .iel-stamp{display:flex;align-items:center;justify-content:center;flex:0 0 96px;width:96px;
  height:96px;border:2px solid var(--iel-accent);border-radius:9999px;text-align:center}
.mfp.mfp-iel.mfp-native-generated .iel-stamp-t{font-size:9px;line-height:1.25;font-weight:700;text-transform:uppercase;
  color:var(--iel-accent)}

/* CTA -------------------------------------------------------------------- */
.mfp.mfp-iel.mfp-native-generated .iel-cta{display:flex;justify-content:flex-end;margin-top:32px}
.mfp.mfp-iel.mfp-native-generated button.iel-submit[type="submit"]{display:inline-flex;align-items:center;gap:6px;
  width:auto!important;padding:10px 24px!important;border:0!important;border-radius:6px!important;
  background:var(--iel-primary)!important;color:#fff!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;font-weight:600!important;
  letter-spacing:normal!important;text-transform:none!important;cursor:pointer!important;
  box-shadow:none!important}
.mfp.mfp-iel.mfp-native-generated button.iel-submit .iel-chk{display:block;flex:0 0 16px;width:16px;height:16px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%23ffffff' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M20 6 9 17l-5-5'%2F%3E%3C%2Fsvg%3E") center/16px 16px no-repeat}
.mfp.mfp-iel.mfp-native-generated button.iel-submit.mf-nav-blocked,.mfp.mfp-iel.mfp-native-generated button.iel-submit[disabled]{opacity:.4!important;
  background:var(--iel-primary)!important;cursor:not-allowed!important}
.mfp.mfp-iel.mfp-native-generated .iel-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-iel.mfp-native-generated .iel-shell,.mfp.mfp-iel.mfp-native-generated .iel-wrap{max-width:none!important;margin:0!important}.mfp.mfp-iel.mfp-native-generated .iel-grid,.mfp.mfp-iel.mfp-native-generated .iel-main,.mfp.mfp-iel.mfp-native-generated .iel-hero-in,.mfp.mfp-iel.mfp-native-generated .iel-card{max-width:none!important;margin-left:0!important;margin-right:0!important}
